import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.BDCokyix.js";const p=JSON.parse('{"title":"Threat Model","description":"","frontmatter":{},"headers":[],"relativePath":"security/threat-model.md","filePath":"security/threat-model.md","lastUpdated":1780254295000}'),r={name:"security/threat-model.md"};function s(l,e,n,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="threat-model" tabindex="-1">Threat Model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat Model&quot;">​</a></h1><p>This page captures a practical threat model for Soma’s current architecture. It is not a formal verification document; it is meant to guide engineering decisions and reviews.</p><h2 id="high-level-goals" tabindex="-1">High-level goals <a class="header-anchor" href="#high-level-goals" aria-label="Permalink to &quot;High-level goals&quot;">​</a></h2><ul><li>Keep user data local-first (no mandatory cloud).</li><li>Prevent unauthorized peers from joining or reading space data.</li><li>Keep infrastructure services &quot;connectivity-only&quot; (no plaintext user content).</li><li>Make it hard for cache-only peers (bots) to become a source of truth.</li></ul><h2 id="assets-to-protect" tabindex="-1">Assets to protect <a class="header-anchor" href="#assets-to-protect" aria-label="Permalink to &quot;Assets to protect&quot;">​</a></h2><ul><li><strong>Identity keys</strong>: libp2p private keys (PeerId source of truth).</li><li><strong>Capabilities</strong>: membership and issuer delegation artifacts.</li><li><strong>Local data</strong>: documents, metadata, and cached state in local storage.</li><li><strong>Blobs</strong>: content-addressed binary assets stored outside collaborative state.</li><li><strong>Admin tokens</strong>: any bearer tokens used for mode-gated HTTP control planes (admin mode).</li></ul><h2 id="trust-boundaries" tabindex="-1">Trust boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust boundaries&quot;">​</a></h2><h3 id="desktop-boundary" tabindex="-1">Desktop boundary <a class="header-anchor" href="#desktop-boundary" aria-label="Permalink to &quot;Desktop boundary&quot;">​</a></h3><ul><li><strong>Renderer (untrusted UI surface)</strong> → <strong>Tauri <code>src-tauri</code> host (trusted local backend, including the <code>soma-daemon</code> and <code>soma-agentd</code> libraries embedded via the <code>desktop-daemon</code> / <code>desktop-agent</code> crates)</strong>.</li><li>There is no separate daemon process and no IPC socket. Daemon operations are plain Rust calls inside the host — the only boundary is the WebView-renderer ↔ host bridge, which is constrained to the <code>#[tauri::command]</code> surface exposed by <code>desktop-commands</code> (and gated by Tauri&#39;s capability/permission config).</li></ul><h3 id="p2p-boundary" tabindex="-1">P2P boundary <a class="header-anchor" href="#p2p-boundary" aria-label="Permalink to &quot;P2P boundary&quot;">​</a></h3><ul><li>Remote peers and bots are <strong>untrusted by default</strong>.</li><li>All network inputs (messages, blobs, metadata) must be treated as attacker-controlled.</li></ul><h3 id="infrastructure-boundary" tabindex="-1">Infrastructure boundary <a class="header-anchor" href="#infrastructure-boundary" aria-label="Permalink to &quot;Infrastructure boundary&quot;">​</a></h3><ul><li><code>somad relay</code> and <code>somad rendezvous</code> are <strong>connectivity-only</strong>; they should not store or process application content beyond what libp2p protocols require.</li></ul><h2 id="threats-and-mitigations-by-area" tabindex="-1">Threats and mitigations (by area) <a class="header-anchor" href="#threats-and-mitigations-by-area" aria-label="Permalink to &quot;Threats and mitigations (by area)&quot;">​</a></h2><h3 id="_1-local-compromise-same-machine" tabindex="-1">1) Local compromise (same machine) <a class="header-anchor" href="#_1-local-compromise-same-machine" aria-label="Permalink to &quot;1) Local compromise (same machine)&quot;">​</a></h3><p>Threats:</p><ul><li>A malicious renderer payload triggers unsafe command calls into the Tauri host (confused deputy).</li><li>Another local process tampers with the daemon&#39;s on-disk state (SQLite DB, blob directory, libp2p identity key) under the user&#39;s home directory.</li></ul><p>Mitigations:</p><ul><li>Keep the renderer ↔ host command surface narrow; route privileged operations through the small, audited <code>desktop-commands</code> surface and Tauri&#39;s capability/permission config.</li><li>Store the libp2p identity and DBs under the app data dir (<code>~/Library/Application Support/Soma/</code> on macOS, <code>~/.local/share/soma/</code> on Linux) with default file permissions and let the OS isolation do its job; we do not rely on app-level authentication for &quot;is this the same user.&quot;</li><li>See ADR-0001 for why we no longer maintain a separate daemon process / Unix-socket IPC surface.</li></ul><h3 id="_2-unauthorized-membership-capability-forgery" tabindex="-1">2) Unauthorized membership / capability forgery <a class="header-anchor" href="#_2-unauthorized-membership-capability-forgery" aria-label="Permalink to &quot;2) Unauthorized membership / capability forgery&quot;">​</a></h3><p>Threats:</p><ul><li>A peer forges membership artifacts or replays old approvals.</li><li>A bot issues memberships without being delegated (or after delegation expired).</li></ul><p>Mitigations:</p><ul><li>Treat capabilities as signed artifacts; verify signatures and expiry consistently (ADR-0002).</li><li>Keep join deciders policy-driven (bot auto-approve only with valid issuer capability; otherwise manual).</li><li>Persist join decisions and issuance events for auditability (storage layer).</li></ul><p>Known gaps / follow-ups:</p><ul><li>Canonical signing format across versions is still an explicit follow-up (see repo notes about canonical CBOR).</li></ul><h3 id="_3-blob-integrity-and-cache-poisoning" tabindex="-1">3) Blob integrity and cache poisoning <a class="header-anchor" href="#_3-blob-integrity-and-cache-poisoning" aria-label="Permalink to &quot;3) Blob integrity and cache poisoning&quot;">​</a></h3><p>Threats:</p><ul><li>A malicious peer serves incorrect bytes for a CID.</li><li>A cache-only peer persists unverified bytes and later serves them (poisoned cache).</li></ul><p>Mitigations:</p><ul><li>Always verify that bytes match the claimed CID before persisting/serving.</li><li>Enforce size limits on ingress/egress for blob transfers.</li><li>Keep VDFs (bots) cache-only: no upload endpoints; cache writes only as a side-effect of fetch+verify.</li></ul><h3 id="_4-denial-of-service-network-and-local" tabindex="-1">4) Denial of service (network and local) <a class="header-anchor" href="#_4-denial-of-service-network-and-local" aria-label="Permalink to &quot;4) Denial of service (network and local)&quot;">​</a></h3><p>Threats:</p><ul><li>Flood join requests, mailbox items, pubsub messages, or blob requests.</li><li>Exhaust disk via large blobs or many cached objects.</li><li>Tie up CPU via expensive verification or agent workloads.</li></ul><p>Mitigations:</p><ul><li>Bound message sizes (protocol-level maximums) and enforce limits at controllers.</li><li>Use backpressure and bounded queues for event handling (peer event dispatcher).</li><li>Apply cache eviction policy (LRU/TTL/size cap) for VDFs/bots.</li><li>Constrain local compute (agentd job concurrency, max tokens, timeouts).</li></ul><h3 id="_5-confidentiality-leakage-via-infrastructure" tabindex="-1">5) Confidentiality leakage via infrastructure <a class="header-anchor" href="#_5-confidentiality-leakage-via-infrastructure" aria-label="Permalink to &quot;5) Confidentiality leakage via infrastructure&quot;">​</a></h3><p>Threats:</p><ul><li>Relay or rendezvous operators observe user content.</li></ul><p>Mitigations:</p><ul><li>libp2p connections are encrypted/authenticated; relay forwards encrypted traffic only.</li><li>Keep infra services stateless and minimize logging of sensitive metadata.</li></ul><h2 id="operational-checklist-quick-review" tabindex="-1">Operational checklist (quick review) <a class="header-anchor" href="#operational-checklist-quick-review" aria-label="Permalink to &quot;Operational checklist (quick review)&quot;">​</a></h2><ul><li>New IPC endpoint: does it avoid exposing raw filesystem paths or arbitrary command execution?</li><li>New protocol: are message sizes bounded and inputs validated?</li><li>Blob changes: is CID verification preserved before serve/persist?</li><li>Bot mode HTTP: does it remain read-only? (write surfaces must be mode-gated and authenticated)</li><li>Storage: are migrations applied at startup and errors fatal (no partial startup)?</li></ul>',43)])])}const m=a(r,[["render",s]]);export{p as __pageData,m as default};
